## Code Example

```javascript
// Minimal illustrative code (not production-ready)
class Backend {
  apply(image, opSpec) { throw new Error('not implemented') }
}
class CPUBackend extends Backend {
  apply(image, opSpec) { /* CPU path */ return image }
}
class GPUBackend extends Backend {
  apply(image, opSpec) { /* GPU path, e.g., CUDA/Vulkan */ return image }
}
class Filter {
  constructor(opSpec) { this.opSpec = opSpec }
  render(image, backend) { return backend.apply(image, this.opSpec) }
}
class Pipeline {
  constructor() { this.filters = []; }
  setBackend(b) { this.backend = b }
  addFilter(f) { this.filters.push(f) }
  run(image) { let out = image; for (const f of this.filters) out = f.render(out, this.backend); return out }
}
```

